def jacc(a, b):
    A, B = set(a.split()), set(b.split())
    return len(A & B) / max(1, len(A | B))
docs = ['inverted index terms docs', 'posting lists positions', 'hash table buckets']
print('d1-d2 similarity:', round(jacc(docs[0], docs[1]), 2), '| d1-d3:', round(jacc(docs[0], docs[2]), 2))

