from collections import defaultdict
corpus = {'d1': 'inverted index maps terms', 'd2': 'posting lists store positions'}
idx = defaultdict(list)
for did, text in corpus.items():
    for w in text.split(): idx[w].append(did)
print('index terms:', len(idx), '| "index" ->', idx['index'])

